import { requireSymbol } from '../../symbols/registry';
import type { SymbolPrimitive } from '../../symbols/types';
export const topologyImageSpec={width:1000,height:300,centers:[100,300,500,700,900],y:170,size:80,labels:['Input','Valve','Filter','Regulator','Output'],definitions:['equipment-block','valve','filter','pressure-regulator','equipment-block']};
export function topologyImageFixture(){const spec=topologyImageSpec,canvas=document.createElement('canvas');canvas.width=spec.width;canvas.height=spec.height;const ctx=canvas.getContext('2d')!;ctx.fillStyle='#fff';ctx.fillRect(0,0,spec.width,spec.height);ctx.strokeStyle='#222';ctx.lineWidth=2;ctx.font='18px Arial';ctx.fillStyle='#222';for(const [i,x]of spec.centers.entries()){ctx.fillText(spec.labels[i]!,x-30,80);ctx.save();ctx.translate(x,spec.y);ctx.scale(spec.size,-spec.size);ctx.lineWidth=2/spec.size;for(const p of requireSymbol('gas-process-demo',spec.definitions[i]!).geometry)draw(ctx,p);ctx.restore();if(i<4){ctx.beginPath();ctx.moveTo(x+spec.size/2+4,spec.y);ctx.lineTo(spec.centers[i+1]!-spec.size/2-4,spec.y);ctx.stroke();}}return canvas;}
function draw(ctx:CanvasRenderingContext2D,p:SymbolPrimitive){ctx.beginPath();if(p.type==='circle')ctx.arc(p.center.x,p.center.y,p.radius,0,Math.PI*2);else if(p.type==='rect')ctx.rect(p.position.x,p.position.y,p.width,p.height);else{const points=p.type==='line'?[p.start,p.end]:p.points;points.forEach((q,i)=>i?ctx.lineTo(q.x,q.y):ctx.moveTo(q.x,q.y));if(p.type==='polygon')ctx.closePath();}ctx.stroke();}
